import{_ as n,o as a,c as t,a8 as e}from"./chunks/framework.CAT8sTE0.js";const g=JSON.parse('{"title":"DevAgent Harness","description":"","frontmatter":{},"headers":[],"relativePath":"dev-agent-harness/README.md","filePath":"dev-agent-harness/README.md"}'),l={name:"dev-agent-harness/README.md"};function i(o,s,d,p,r,c){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="devagent-harness" tabindex="-1">DevAgent Harness <a class="header-anchor" href="#devagent-harness" aria-label="Permalink to &quot;DevAgent Harness&quot;">​</a></h1><p>一套面向<strong>软件开发</strong>的通用 AI 工作流工具箱。让 AI Agent 按照规范化的流程完成开发任务：先计划，再实现，再验证，再审查。</p><p>不限定语言、不限定领域——前端、后端、基础设施，任何开发任务都能用。</p><h2 id="核心理念" tabindex="-1">核心理念 <a class="header-anchor" href="#核心理念" aria-label="Permalink to &quot;核心理念&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>可靠性 = 流程约束 + 精准上下文 + 阶段产出 + 经验闭环</span></span></code></pre></div><table tabindex="0"><thead><tr><th>理念</th><th>含义</th></tr></thead><tbody><tr><td>流程约束</td><td>工作流定义好阶段顺序，AI 不能跳步</td></tr><tr><td>精准上下文</td><td>每个阶段只加载需要的 skill + 相关文件，不浪费 token</td></tr><tr><td>阶段产出</td><td>每步输出一个 markdown 文件，既是证据也是下游输入</td></tr><tr><td>经验闭环</td><td>踩坑记录沉淀为 knowledge，下次同类任务自动带上</td></tr></tbody></table><h2 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h2><p>采用<strong>通用层 + 项目层</strong>的两层结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│         Harness 仓库（本仓库）            │</span></span>
<span class="line"><span>│                                         │</span></span>
<span class="line"><span>│  workflows/       工作流（模板）    │</span></span>
<span class="line"><span>│  skills/          通用技能                │</span></span>
<span class="line"><span>│  context-rules/   上下文加载策略          │</span></span>
<span class="line"><span>│  skill-interface.md  Skill 接口规范       │</span></span>
<span class="line"><span>│  templates/       默认产出模板            │</span></span>
<span class="line"><span>│  tools/           运行时工具（verify 等）  │</span></span>
<span class="line"><span>│  hooks/           门禁脚本（gate-check）  │</span></span>
<span class="line"><span>└──────────────────┬──────────────────────┘</span></span>
<span class="line"><span>                   │ 通过 submodule 嵌入</span></span>
<span class="line"><span>                   ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│            目标项目（项目层）              │</span></span>
<span class="line"><span>│                                         │</span></span>
<span class="line"><span>│  knowledge/                             │</span></span>
<span class="line"><span>│  ├── skills/      项目定制的阶段技能      │</span></span>
<span class="line"><span>│  ├── workflow/     项目定制的工作流  │</span></span>
<span class="line"><span>│  ├── standards/   项目编码规范            │</span></span>
<span class="line"><span>│  ├── patterns/    项目最佳实践            │</span></span>
<span class="line"><span>│  ├── lessons/     项目经验教训            │</span></span>
<span class="line"><span>│  └── _index.md    知识索引               │</span></span>
<span class="line"><span>│                                         │</span></span>
<span class="line"><span>│  .harness/workspace/  运行时产物          │</span></span>
<span class="line"><span>└─────────────────────────────────────────┘</span></span></code></pre></div><ul><li><strong>通用层</strong>（本仓库）：定义工作流（模板）、Skill 接口规范、通用技能、门禁与验证工具。所有项目共用，由 Harness 维护者更新。</li><li><strong>项目层</strong>（<code>knowledge/</code>）：项目特定的技能实现、<strong>工作流实例</strong>（<code>workflow/</code>）、编码规范、经验教训。由项目团队 + AI（knowledge-init）共同维护。</li><li><strong>工作流 = 模板 + 项目实例</strong>：通用工作流是<strong>模板</strong>（骨架），测试命令/通过标准由项目定制；<code>knowledge-init workflow-init</code> 把模板实例化到项目层并增强（见 docs/workflow-spec.md）。</li></ul><h2 id="工作流" tabindex="-1">工作流 <a class="header-anchor" href="#工作流" aria-label="Permalink to &quot;工作流&quot;">​</a></h2><p>内置 6 种工作流（<code>workflows/{name}/workflow.yaml</code>），覆盖常见场景：</p><table tabindex="0"><thead><tr><th>工作流</th><th>阶段</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>feature</strong></td><td>前置确认 → 设计 → 计划 → 实施 → 测试 → 审查 → 复盘 → Git</td><td>新功能开发与代码重构</td></tr><tr><td><strong>bugfix</strong></td><td>计划 → 实施 → 测试 → 审查 → 复盘 → Git</td><td>Bug 修复</td></tr><tr><td><strong>requirements</strong></td><td>需求采集 → 撰写 → 评审 → 复盘</td><td>需求脑暴（非代码任务，产出需求文档含验收标准，作为 feature 前置输入）</td></tr><tr><td><strong>project-init</strong></td><td>初始化 → 复盘 → Git</td><td>从零搭建项目</td></tr><tr><td><strong>skill-creation</strong></td><td>设计 → 实施 → 测试 → 复盘</td><td>创建/重构 harness 技能（非代码任务）</td></tr><tr><td><strong>workflow-creation</strong></td><td>设计 → 实施 → 测试 → 复盘</td><td>创建工作流的流程</td></tr></tbody></table><p>每个阶段都有明确的输入/输出定义和 gate 控制（需用户确认才能进入下一阶段）。</p><p><strong>工作流 = 自包含定义</strong>：步骤定义 + 产出物要求（sections）+ 测试手段（verify.checks）自包含在一个目录里；项目可用 <code>knowledge-init workflow-init</code> 把模板实例化到 <code>knowledge/workflow/</code> 并定制（增删阶段/改 gate/绑项目测试命令）。详见 <code>docs/workflow-spec.md</code>。</p><h2 id="通用技能-通用层-skills-分四组" tabindex="-1">通用技能（通用层 <code>skills/</code> 分四组） <a class="header-anchor" href="#通用技能-通用层-skills-分四组" aria-label="Permalink to &quot;通用技能（通用层 \`skills/\` 分四组）&quot;">​</a></h2><blockquote><p>仓库根的 <code>skills/</code> 按职责分四组，项目层（<code>knowledge/skills/</code>）可按 <code>skill-interface.md</code> 的加载优先级覆盖同名的框架/工具类技能。</p></blockquote><table tabindex="0"><thead><tr><th>分组</th><th>目录</th><th>技能</th><th>说明</th></tr></thead><tbody><tr><td>框架层</td><td><code>skills/framework/</code></td><td><strong>reflecting</strong></td><td>项目复盘 + 经验收集。两阶段：自动复盘生成草稿 → 手动收集到知识库</td></tr><tr><td></td><td></td><td><strong>state-checkpoint</strong></td><td>状态记录与断点恢复。支持任务中断后从断点继续</td></tr><tr><td></td><td></td><td><strong>env-check</strong></td><td>环境就绪检查。pre_task 自动执行，产出环境快照，防止基于错误假设开工</td></tr><tr><td></td><td></td><td><strong>orchestrate</strong></td><td>编排桥技能：主 agent 如何按 next → Agent → validate → advance 循环执行</td></tr><tr><td></td><td></td><td><strong>precondition</strong></td><td>feature 前置条件确认：验收标准来源（需求文档引用或简要需求文档），无则不进入设计</td></tr><tr><td></td><td></td><td><strong>hook-init</strong></td><td>hook 初始化：安装/接线门禁脚本（gate-check / check-verify）</td></tr><tr><td>技能自举</td><td><code>skills/skill-creation/</code></td><td><strong>skill-design</strong></td><td>设计新技能</td></tr><tr><td></td><td></td><td><strong>skill-evolution</strong></td><td>技能自成长。汇总 skill-logs，发现技能不足并持续优化</td></tr><tr><td></td><td></td><td><strong>skill-implement</strong></td><td>实现技能</td></tr><tr><td></td><td></td><td><strong>skill-test</strong></td><td>测试技能</td></tr><tr><td>工作流自举</td><td><code>skills/workflow-creation/</code></td><td><strong>workflow-design / workflow-implement / workflow-test</strong></td><td>设计/实现/测试工作流（创建工作流的流程）</td></tr><tr><td>工具类</td><td><code>skills/tools/</code></td><td><strong>knowledge-init</strong></td><td>知识库初始化与维护。扫描项目代码自动生成规范、模式、阶段技能；<code>workflow-init</code> 子命令实例化项目定制工作流</td></tr><tr><td></td><td></td><td><strong>project-init</strong></td><td>从零开始的项目初始化（技术选型 + 标准定制 + 脚手架搭建）</td></tr><tr><td></td><td></td><td><strong>tech-audit</strong></td><td>技术审计</td></tr><tr><td>框架模板</td><td><code>skills/domain-templates/</code></td><td>designing / task-planning / implementing / testing / reviewing</td><td>5 个框架级标准 skill 模板；由 <code>knowledge-init skills</code> 继承生成项目层 skill</td></tr></tbody></table><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><h3 id="_1-作为-submodule-添加到项目" tabindex="-1">1. 作为 submodule 添加到项目 <a class="header-anchor" href="#_1-作为-submodule-添加到项目" aria-label="Permalink to &quot;1. 作为 submodule 添加到项目&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> submodule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">harness-repo-ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .harness</span></span></code></pre></div><h3 id="_2-初始化知识库" tabindex="-1">2. 初始化知识库 <a class="header-anchor" href="#_2-初始化知识库" aria-label="Permalink to &quot;2. 初始化知识库&quot;">​</a></h3><p>在 AI 对话中说：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初始化知识库</span></span></code></pre></div><p>AI 会执行 <code>knowledge-init scan</code> 扫描项目代码，生成 <code>knowledge/</code> 目录下的规范、模式和阶段技能。</p><h3 id="_2-5-定制项目工作流-可选" tabindex="-1">2.5 定制项目工作流（可选） <a class="header-anchor" href="#_2-5-定制项目工作流-可选" aria-label="Permalink to &quot;2.5 定制项目工作流（可选）&quot;">​</a></h3><p>需要项目专属工作流（测试命令/通过标准与通用模板不同）时：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>knowledge-init workflow-init init feature</span></span></code></pre></div><p>把通用模板实例化到 <code>knowledge/workflow/{name}/</code>，绑定项目命令池后按需增强（增删阶段、改 gate、改产出物要求）。详见 <code>docs/workflow-spec.md</code> §4.5。</p><h3 id="_3-开始开发" tabindex="-1">3. 开始开发 <a class="header-anchor" href="#_3-开始开发" aria-label="Permalink to &quot;3. 开始开发&quot;">​</a></h3><p>给 AI 一个开发任务，它会自动识别工作流并按阶段执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实现用户登录注册功能</span></span></code></pre></div><p>AI 将按 前置确认（验收标准）→ 设计 → 计划 → 实施 → 测试 → 审查 的流程逐步推进，每个阶段产出结构化文件并等待确认。</p><h3 id="_4-收集经验" tabindex="-1">4. 收集经验 <a class="header-anchor" href="#_4-收集经验" aria-label="Permalink to &quot;4. 收集经验&quot;">​</a></h3><p>任务完成后，AI 自动生成经验草稿。审核后可收集到知识库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>收集第 1、3 条经验</span></span></code></pre></div><h3 id="_5-技能进化" tabindex="-1">5. 技能进化 <a class="header-anchor" href="#_5-技能进化" aria-label="Permalink to &quot;5. 技能进化&quot;">​</a></h3><p>定期汇总技能执行记录，优化技能：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>skill-evolution review</span></span></code></pre></div><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.harness/</span></span>
<span class="line"><span>├── harness.md              # Agent 入口（必读）</span></span>
<span class="line"><span>├── skill-interface.md      # Skill 接口规范</span></span>
<span class="line"><span>├── workflow-schema.json    # 工作流 schema（格式校验）</span></span>
<span class="line"><span>├── context-rules/          # 上下文加载策略</span></span>
<span class="line"><span>│   ├── file-discovery.md</span></span>
<span class="line"><span>│   └── loading-strategy.md</span></span>
<span class="line"><span>├── docs/                   # 设计文档（DESIGN.md / orchestrator-design.md / workflow-spec.md）</span></span>
<span class="line"><span>├── skills/                 # 通用层技能（分组见「通用技能」表）</span></span>
<span class="line"><span>│   ├── framework/          # 框架层：reflecting / state-checkpoint / env-check / orchestrate / precondition / hook-init</span></span>
<span class="line"><span>│   ├── skill-creation/     # 技能自举：skill-design / skill-evolution / skill-implement / skill-test</span></span>
<span class="line"><span>│   ├── workflow-creation/  # 工作流自举：workflow-design / workflow-implement / workflow-test</span></span>
<span class="line"><span>│   ├── tools/              # 工具类：knowledge-init / project-init / tech-audit</span></span>
<span class="line"><span>│   └── domain-templates/   # 框架模板：designing / task-planning / implementing / testing / reviewing</span></span>
<span class="line"><span>├── templates/              # 默认产出模板</span></span>
<span class="line"><span>├── tools/                  # 运行时工具：verify.js / env-check.js / workflow-lib.js / workflow-init.js / skill-log.js / review-brief.js / simple-yaml.js / lessons-apply.js / knowledge-index.js</span></span>
<span class="line"><span>├── hooks/                  # 门禁脚本：gate-check.js / check-verify.js / post-tool-log.js / lib.js / install.js</span></span>
<span class="line"><span>├── workflows/              # 工作流（6 个，含 workflow.yaml + check/）</span></span>
<span class="line"><span>│   ├── feature/            # 新功能开发与代码重构</span></span>
<span class="line"><span>│   ├── bugfix/             # Bug 修复</span></span>
<span class="line"><span>│   ├── requirements/       # 需求脑暴（非代码任务）</span></span>
<span class="line"><span>│   ├── project-init/       # 项目初始化</span></span>
<span class="line"><span>│   ├── skill-creation/     # 创建技能的技能</span></span>
<span class="line"><span>│   └── workflow-creation/  # 创建工作流的流程（含 check/workflow-check.js）</span></span>
<span class="line"><span>└── workspace/              # 运行时产物（gitignore）</span></span>
<span class="line"><span>    └── {task-id}/</span></span>
<span class="line"><span>        ├── task.md</span></span>
<span class="line"><span>        ├── design.md</span></span>
<span class="line"><span>        ├── task-plan.md</span></span>
<span class="line"><span>        ├── changes.md</span></span>
<span class="line"><span>        ├── test-report.md</span></span>
<span class="line"><span>        ├── review-report.md</span></span>
<span class="line"><span>        ├── lessons-draft.md</span></span>
<span class="line"><span>        ├── checkpoint.json</span></span>
<span class="line"><span>        └── verify/verification-result.json   # 验证证据（他证）</span></span></code></pre></div><p>项目层额外目录：<code>knowledge/workflow/{name}/</code>（项目定制工作流，git 跟踪）。</p><h2 id="关键特性" tabindex="-1">关键特性 <a class="header-anchor" href="#关键特性" aria-label="Permalink to &quot;关键特性&quot;">​</a></h2><ul><li><strong>流程约束</strong>：工作流定义阶段顺序，AI 不能跳步，每个阶段必须有产出</li><li><strong>按需加载</strong>：每个阶段只加载需要的 skill 和上下文，不浪费 token</li><li><strong>阶段产出</strong>：每步输出 markdown 文件，既是证据也是下游输入</li><li><strong>经验闭环</strong>：踩坑记录沉淀为知识，下次同类任务自动带上</li><li><strong>技能自成长</strong>：通过 skill-log 记录执行情况，持续优化技能</li><li><strong>断点恢复</strong>：支持任务中断后从 checkpoint 继续执行</li><li><strong>零依赖</strong>：核心产物就是文件，不依赖数据库或复杂框架</li><li><strong>工作流化</strong>：工作流 = 自包含定义（步骤+产出要求+测试手段）；通用模板 + 项目定制（<code>knowledge/workflow/</code>）；创建工作流的流程（workflow-creation）</li><li><strong>验证他证</strong>：verify 命令只能来自工作流声明 + 项目命令池（LLM 不能自选），gate 对账证据（文档/技能任务只跑对应 check，不跑项目测试）</li><li><strong>门禁宿主适配</strong>：gate-check 按工作流定义校验产出物；WorkBuddy 用 PreToolUse 硬阻断，Claude 等用 PostToolUse</li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>MIT</p>`,46)])])}const k=n(l,[["render",i]]);export{g as __pageData,k as default};
